#!/usr/bin/env node
// ============================================================
// Phoenix Backend — Local JWKS Test Utility
// PHX-AUTH-002 — Hosted Auth Vendor Decision & Production Resolver
// ------------------------------------------------------------
// QA-only utility. Generates a local, test-only RSA keypair (or reuses
// one already generated by a prior run of this script in the same
// working directory) and serves it as a JWKS document over plain HTTP,
// so oidc-jwt mode can be exercised end-to-end WITHOUT signing up for
// a real hosted auth provider account.
//
// This key is NEVER a real production credential, is written only to
// .auth-test/ (gitignored — see .gitignore entry added this sprint),
// and this script refuses to run when NODE_ENV=production as an extra
// guard against accidental misuse outside local QA.
//
// Usage:
//   node scripts/auth-test-jwks.mjs [--port 4001]
//
// Then point the backend at it for a QA run:
//   PHOENIX_AUTH_MODE=oidc-jwt \
//   PHOENIX_AUTH_ISSUER=https://phoenix-auth-test.local \
//   PHOENIX_AUTH_AUDIENCE=phoenix-backend-test \
//   PHOENIX_AUTH_JWKS_URI=http://localhost:4001/.well-known/jwks.json \
//   PHOENIX_AUTH_PROVIDER=test-local \
//   pnpm dev
//
// Mint a matching token with scripts/auth-test-token.mjs (same
// .auth-test/ directory, same key).
// ============================================================

import { generateKeyPair, exportJWK } from 'jose';
import { createServer } from 'node:http';
import { mkdirSync, writeFileSync, readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';

if ((process.env.NODE_ENV ?? '').toLowerCase() === 'production') {
  console.error(
    '[auth-test-jwks] Refusing to run with NODE_ENV=production. This is a QA-only utility.'
  );
  process.exit(1);
}

const args = process.argv.slice(2);
const portFlagIndex = args.indexOf('--port');
const port = portFlagIndex >= 0 ? Number.parseInt(args[portFlagIndex + 1], 10) : 4001;

const TEST_DIR = join(process.cwd(), '.auth-test');
const PRIVATE_KEY_PATH = join(TEST_DIR, 'private-key.jwk.json');
const PUBLIC_JWKS_PATH = join(TEST_DIR, 'jwks.json');
const KID = 'phoenix-auth-test-key-1';

async function ensureKeypair() {
  if (existsSync(PRIVATE_KEY_PATH) && existsSync(PUBLIC_JWKS_PATH)) {
    console.log(`[auth-test-jwks] Reusing existing test keypair at ${TEST_DIR}`);
    return;
  }

  console.log('[auth-test-jwks] Generating new local test-only RSA keypair (RS256)...');
  const { publicKey, privateKey } = await generateKeyPair('RS256', { modulusLength: 2048 });

  const privateJwk = await exportJWK(privateKey);
  const publicJwk = await exportJWK(publicKey);
  privateJwk.kid = KID;
  privateJwk.alg = 'RS256';
  publicJwk.kid = KID;
  publicJwk.alg = 'RS256';
  publicJwk.use = 'sig';

  mkdirSync(TEST_DIR, { recursive: true });
  writeFileSync(PRIVATE_KEY_PATH, JSON.stringify(privateJwk, null, 2), { mode: 0o600 });
  writeFileSync(PUBLIC_JWKS_PATH, JSON.stringify({ keys: [publicJwk] }, null, 2));

  console.log(`[auth-test-jwks] Test keypair written to ${TEST_DIR} (test-only, gitignored).`);
}

async function main() {
  await ensureKeypair();

  const jwks = JSON.parse(readFileSync(PUBLIC_JWKS_PATH, 'utf8'));

  const server = createServer((req, res) => {
    if (req.url === '/.well-known/jwks.json' && req.method === 'GET') {
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify(jwks));
      return;
    }
    res.writeHead(404, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ error: 'not_found' }));
  });

  server.listen(port, () => {
    console.log(`[auth-test-jwks] Serving JWKS at http://localhost:${port}/.well-known/jwks.json`);
    console.log('[auth-test-jwks] Set these to exercise oidc-jwt mode:');
    console.log('  PHOENIX_AUTH_MODE=oidc-jwt');
    console.log('  PHOENIX_AUTH_ISSUER=https://phoenix-auth-test.local');
    console.log('  PHOENIX_AUTH_AUDIENCE=phoenix-backend-test');
    console.log(`  PHOENIX_AUTH_JWKS_URI=http://localhost:${port}/.well-known/jwks.json`);
    console.log('  PHOENIX_AUTH_PROVIDER=test-local');
    console.log('[auth-test-jwks] Mint a matching token with scripts/auth-test-token.mjs. Ctrl+C to stop.');
  });
}

void main();
